int path_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0;
    int j = 0;
    int error = 0;

    if (!sb || !from || fromlen < 0 || !to || tolen < 0) {
        return -EIO;
    }

    if (tolen < 1) {
        return -ENAMETOOLONG;
    }

    to[0] = '\0';

    for (i = 0; i < fromlen; i++) {
        unsigned char c = from[i];

        if (j + 1 >= tolen) {
            return -ENAMETOOLONG;
        }

        if (c == '/') {
            if (j == 0 || to[j - 1] != '/') {
                to[j++] = '/';
            }
        } else {
            to[j++] = c;
        }
    }

    if (j >= tolen) {
        return -ENAMETOOLONG;
    }

    to[j] = '\0';

    return 0;
}
